class Solution {
public:
	vector<vector<string>> wordSquares(vector<string>& words) {
		unordered_map<string, unordered_set<string>> prefixMap;  // prefix -> set of words that has it as prefix
		for (auto w : words) {
			add(prefixMap, w);
		}
		vector<vector<string>> ans;
		int len = words[0].length();
		vector<string> curr(len, string(len, ' '));
		// prefix map + DFS
		// state: current placed strings
		search(words, prefixMap, ans, curr, 0);
		return ans;
	}
private:
	void add(unordered_map<string, unordered_set<string>>& prefix, string& w) {
		int n = w.length();
		string currW(n, ' ');
		prefix[currW].insert(w);
		for (int i = 0; i < n; i++) {
			currW[i] = w[i];
			prefix[currW].insert(w);
		}
	}
	void search(vector<string>& words, unordered_map<string, unordered_set<string>>& prefixMap, vector<vector<string>>& ans, vector<string>& curr, int i) {
		if (i == curr.size()) {
			ans.push_back(curr);
			return;
		}
		for (auto& w : prefixMap[curr[i]]) {    // only need to check the words prefixed by curr[i] 
			string ori = curr[i];
			curr[i] = w;
			bool ok = true;
			for (int j = i+1; j < curr.size() && ok; j++) { // check transpose
				curr[j][i] = w[j];
				if (!prefixMap.count(curr[j])) {    // non-existing prefix -> can't place w here
					ok = false;
				}
			}
			if (ok) {   // keep searching
				search(words, prefixMap, ans, curr, i+1);
			}
			for (int j = i+1; j < curr.size(); j++) {   // recover the state
				curr[j][i] = ' ';
			}
			curr[i] = ori;
		}
	}
};

class Trie:
    def __init__(self):
        self.children = [None] * 26
        self.v = []

    def insert(self, w, i):
        node = self
        for c in w:
            idx = ord(c) - ord('a')
            if node.children[idx] is None:
                node.children[idx] = Trie()
            node = node.children[idx]
            node.v.append(i)

    def search(self, w):
        node = self
        for c in w:
            idx = ord(c) - ord('a')
            if node.children[idx] is None:
                return []
            node = node.children[idx]
        return node.v


class Solution:
    def wordSquares(self, words: List[str]) -> List[List[str]]:
        def dfs(t):
            if len(t) == len(words[0]):
                ans.append(t[:])
                return
            idx = len(t)
            pref = [v[idx] for v in t]
            indexes = trie.search(''.join(pref))
            for i in indexes:
                t.append(words[i])
                dfs(t)
                t.pop()

        trie = Trie()
        ans = []
        for i, w in enumerate(words):
            trie.insert(w, i)
        for w in words:
            dfs([w])
        return ans

class Trie {
    Trie[] children = new Trie[26];
    List<Integer> v = new ArrayList<>();

    void insert(String word, int i) {
        Trie node = this;
        for (char c : word.toCharArray()) {
            c -= 'a';
            if (node.children[c] == null) {
                node.children[c] = new Trie();
            }
            node = node.children[c];
            node.v.add(i);
        }
    }

    List<Integer> search(String pref) {
        Trie node = this;
        for (char c : pref.toCharArray()) {
            c -= 'a';
            if (node.children[c] == null) {
                return Collections.emptyList();
            }
            node = node.children[c];
        }
        return node.v;
    }
}

class Solution {
    private Trie trie = new Trie();
    private String[] words;
    private List<List<String>> ans = new ArrayList<>();

    public List<List<String>> wordSquares(String[] words) {
        this.words = words;
        for (int i = 0; i < words.length; ++i) {
            trie.insert(words[i], i);
        }

        List<String> t = new ArrayList<>();
        for (String w : words) {
            t.add(w);
            dfs(t);
            t.remove(t.size() - 1);
        }
        return ans;
    }

    private void dfs(List<String> t) {
        if (t.size() == words[0].length()) {
            ans.add(new ArrayList<>(t));
            return;
        }
        int idx = t.size();
        StringBuilder pref = new StringBuilder();
        for (String x : t) {
            pref.append(x.charAt(idx));
        }
        List<Integer> indexes = trie.search(pref.toString());
        for (int i : indexes) {
            t.add(words[i]);
            dfs(t);
            t.remove(t.size() - 1);
        }
    }
}

type Trie struct {
	children [26]*Trie
	v        []int
}

func newTrie() *Trie {
	return &Trie{}
}
func (this *Trie) insert(word string, i int) {
	node := this
	for _, c := range word {
		c -= 'a'
		if node.children[c] == nil {
			node.children[c] = newTrie()
		}
		node = node.children[c]
		node.v = append(node.v, i)
	}
}
func (this *Trie) search(word string) []int {
	node := this
	for _, c := range word {
		c -= 'a'
		if node.children[c] == nil {
			return []int{}
		}
		node = node.children[c]
	}
	return node.v
}

func wordSquares(words []string) [][]string {
	trie := newTrie()
	for i, w := range words {
		trie.insert(w, i)
	}
	ans := [][]string{}
	var dfs func([]string)
	dfs = func(t []string) {
		if len(t) == len(words[0]) {
			cp := make([]string, len(t))
			copy(cp, t)
			ans = append(ans, cp)
			return
		}
		idx := len(t)
		pref := []byte{}
		for _, v := range t {
			pref = append(pref, v[idx])
		}
		indexes := trie.search(string(pref))
		for _, i := range indexes {
			t = append(t, words[i])
			dfs(t)
			t = t[:len(t)-1]
		}
	}
	for _, w := range words {
		dfs([]string{w})
	}
	return ans
}
